#!/usr/bin/env python3
"""Serve the .webp siblings generated by tools/optimize_images.py to browsers.

Two rewrites per <img> pointing at a local raster asset that has a .webp
sibling:

  * plain images become a <picture> pair, so the PNG/JPEG stays as the
    fallback and only WebP-capable browsers download the smaller file:

        <img src="/assets/venomous-icon.png" alt="" width="64" height="64">
        <picture><source srcset="/assets/venomous-icon.webp" type="image/webp">
        <img src="/assets/venomous-icon.png" alt="" width="64" height="64"></picture>

  * [data-org-avatar] images are left unwrapped and only switched over: their
    src is replaced at runtime with the live GitLab avatar (script.js), and a
    <source> would win over that. Swapping the fallback file is enough.

Acceptance image-set() pairs for the assets referenced from CSS live in the
stylesheets themselves.

Run from the repo root:  python3 tools/apply_image_sources.py

Idempotent: images already inside a <picture> pair are skipped, as are images
that already carry a srcset.
"""

from __future__ import annotations

import re
from pathlib import Path

IMG = re.compile(r"<img\b[^>]*>")
SRC = re.compile(r'src="(?P<src>/assets/(?P<name>[^"?]+)\.(?:png|jpg|jpeg))"')
WRAPPED = re.compile(r"<picture>\s*<source[^>]*>\s*$")


def webp_sibling(root: Path, name: str) -> str | None:
    candidate = root / "assets" / f"{name}.webp"
    if candidate.is_file():
        return f"/assets/{name}.webp"
    return None


def rewrite(root: Path, source: str) -> tuple[str, int, int]:
    wrapped = swapped = 0

    def fix(match: re.Match) -> str:
        nonlocal wrapped, swapped
        tag = match.group(0)
        if "srcset=" in tag:
            return tag
        found = SRC.search(tag)
        if not found:
            return tag
        sibling = webp_sibling(root, found.group("name"))
        if not sibling:
            return tag
        if "data-org-avatar" in tag:
            swapped += 1
            return tag.replace(found.group(0), f'src="{sibling}"')
        if WRAPPED.search(source[max(0, match.start() - 200) : match.start()]):
            return tag
        wrapped += 1
        return f'<picture><source srcset="{sibling}" type="image/webp">{tag}</picture>'

    return IMG.sub(fix, source), wrapped, swapped


def main() -> None:
    root = Path(__file__).resolve().parent.parent
    total_wrapped = total_swapped = changed = 0
    for html in sorted(root.rglob("*.html")):
        if ".git" in html.parts:
            continue
        source = html.read_text(encoding="utf-8", errors="replace")
        updated, wrapped, swapped = rewrite(root, source)
        if updated != source:
            html.write_text(updated, encoding="utf-8")
            changed += 1
        total_wrapped += wrapped
        total_swapped += swapped
    print(
        f"{changed} file(s) updated: {total_wrapped} <picture> pair(s), "
        f"{total_swapped} fallback src swap(s)"
    )


if __name__ == "__main__":
    main()
